var smtp_default = "---\nlayout: article\ntitle: SMTP\ndescription: Send emails to your Appwrite users using SMTP and Appwrite Messaging.\nback: /docs/\n---\nIf you wish to use a third-party SMTP provider that Appwrite doesn't yet support or host your own SMTP\nserver, you can setup a custom SMTP provider for your project.\n\n{% section #add-provider step=1 title=\"Add provider\" %}\nTo add a custom SMTP server as a provider, navigate to **Messaging** > **Providers** > {% icon icon=\"plus\" size=\"m\" /%} **Add provider** > **Email**.\n{% only_dark %}\n![Add a SMTP provider](/images/docs/messaging/providers/smtp/dark/add-smtp.avif)\n{% /only_dark %}\n{% only_light %}\n![Add a SMTP provider](/images/docs/messaging/providers/smtp/add-smtp.avif)\n{% /only_light %}\n\nGive your provider a name > choose **SMTP** > click **Save and continue**.\nThe provider will be saved to your project, but not enabled until you complete its configuration.\n{% /section %}\n{% section #configure-provider step=2 title=\"Configure provider\" %}\n\nIn the **Configure** step, you will need to provide details from your SMTP dashboard to connect your Appwrite project.\n\nYou will need to provide the following information from your **SMTP dashboard**.\n\n{% table %}\n* Field name\n* Description\n---\n* Host\n* The server address of the SMTP provider.\n---\n* Port\n* The port used for SMTP connections.\n---\n* Username\n* Your SMTP provider account username.\n---\n* Password\n* Your SMTP provider account password.\n---\n* Encryption\n* The type of encryption used. One of SSL or TLS.\n---\n* Auto TLS\n* Automatically uses TLS encryption if available.\n---\n* Mailer\n* The SMTP server or provider.\n---\n* Sender email\n* The provider sends emails from this sender email. The sender email needs to be an email under the configured domain.\n---\n* Sender name\n* The sender name that appears in the emails sent from this provider.\n---\n* Reply-to email\n* The reply-to email that appears in the emails sent from this provider. The reply-to email needs to be an email under the configured domain.\n---\n* Reply-to name\n* The reply-to name that appears in the emails sent from this provider.\n{% /table %}\n\nAfter adding the following details, click **Save and continue** to enable the provider.\n{% /section %}\n\n{% section #test-provider step=3 title=\"Test provider\" %}\nBefore sending your first message,\nmake sure you've configured [a topic](/docs/products/messaging/topics) and [a target](/docs/products/messaging/targets) to send messages to.\n{% tabs %}\n{% tabsitem #console title=\"Console\" %}\nTo send a test message, navigate to **Messaging** > **Messages** > {% icon icon=\"plus\" size=\"m\" /%} **Create message** > **Email**.\n{% only_dark %}\n![Create email message](/images/docs/messaging/messages/dark/create-email-message.avif)\n{% /only_dark %}\n{% only_light %}\n![Create email message](/images/docs/messaging/messages/create-email-message.avif)\n{% /only_light %}\n\nAdd your message and in the targets step, select one of your test targets. Set the schedule to **Now** and click **Send**.\n\nVerify that you can receive the message in your inbox. If not, check for logs in the Appwrite Console or in your provider's logs.\n{% /tabsitem %}\n\n{% tabsitem #server-sdk title=\"Server SDK\" %}\nTo send a message programmatically, use an [Appwrite Server SDK](/docs/sdks#server).\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\n// Init SDK\nconst client = new sdk.Client();\n\nconst messaging = new sdk.Messaging(client);\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>') // Your project ID\n    .setKey('<API_KEY>') // Your secret API key\n;\n\nconst message = await messaging.createEmail({\n  messageId: '<MESSAGE_ID>',\n  subject: '<SUBJECT>',\n  content: '<CONTENT>'\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\n// Init SDK\nlet client = new sdk.Client();\n\nlet messaging = new sdk.Messaging(client);\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>') // Your project ID\n    .setKey('<API_KEY>') // Your secret API key\n;\n\nconst message = await messaging.createEmail({\n  messageId: '<MESSAGE_ID>',\n  subject: '<SUBJECT>',\n  content: '<CONTENT>'\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\Messaging;\n\n$client = new Client();\n\n$client\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<PROJECT_ID>') // Your project ID\n    ->setKey('<API_KEY>') // Your secret API key\n;\n\n$messaging = new Messaging($client);\n\n$result = $messaging->createEmail('<MESSAGE_ID>', '<SUBJECT>', '<CONTENT>');\n```\n```python\nfrom appwrite.client import Client\n\nclient = Client()\n\n(client\n  .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n  .set_project('<PROJECT_ID>') # Your project ID\n  .set_key('<API_KEY>') # Your secret API key\n)\n\nmessaging = Messaging(client)\n\nresult = messaging.create_email(\n    message_id='<MESSAGE_ID>',\n    subject='<SUBJECT>',\n    content='<CONTENT>'\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<PROJECT_ID>') # Your project ID\n    .set_key('<API_KEY>') # Your secret API key\n\nmessaging = Messaging.new(client)\n\nresponse = messaging.create_email(message_id: '<MESSAGE_ID>', subject: '<SUBJECT>', content: '<CONTENT>')\n\nputs response.inspect\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Services;\nusing Appwrite.Models;\nusing Appwrite.Enums;\nusing Appwrite.Enums;\nusing Appwrite.Enums;\n\nvar client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<PROJECT_ID>\") // Your project ID\n    .SetKey(\"<API_KEY>\"); // Your secret API key\n\nvar messaging = new Messaging(client);\n\nMessage result = await messaging.CreateEmail(\n    messageId: \"<MESSAGE_ID>\",\n    subject: \"<SUBJECT>\",\n    content: \"<CONTENT>\");\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\nimport 'package:dart_appwrite/enums.dart';\nimport 'package:dart_appwrite/models.dart';\n\nvoid main() async { // Init SDK\n  Client client = Client();\n  Messaging messaging = Messaging(client);\n\n  client\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>') // Your project ID\n    .setKey('<API_KEY>') // Your secret API key\n  ;\n\n  Future result = await messaging.createEmail(\n    messageId:'<MESSAGE_ID>' ,\n    subject:'<SUBJECT>' ,\n    content:'<CONTENT>' ,\n  );\n\n  result\n    .then((response) {\n      print(response);\n    }).catchError((error) {\n      print(error.response);\n  });\n}\n```\n```kotlin\nimport io.appwrite.Client\nimport io.appwrite.coroutines.CoroutineCallback\nimport io.appwrite.services.Messaging\n\nval client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\") // Your project ID\n    .setKey(\"<API_KEY>\") // Your secret API key\n\nval messaging = Messaging(client)\n\nval response = messaging.createEmail(\n    messageId = \"<MESSAGE_ID>\",\n    subject = \"<SUBJECT>\",\n    content = \"<CONTENT>\",\n)\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.Messaging;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\") // Your project ID\n    .setKey(\"<API_KEY>\"); // Your secret API key\n\nMessaging messaging = new Messaging(client);\n\nmessaging.createEmail(\n    \"<MESSAGE_ID>\",\n    \"<SUBJECT>\",\n    \"<CONTENT>\",\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```swift\nimport Appwrite\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\") // Your project ID\n    .setKey(\"<API_KEY>\") // Your secret API key\n\nlet messaging = Messaging(client)\n\nlet message = try await messaging.createEmail(\n    messageId: \"<MESSAGE_ID>\",\n    subject: \"<SUBJECT>\",\n    content: \"<CONTENT>\"\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::messaging::Messaging;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new()\n        .set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\")\n        .set_project(\"<PROJECT_ID>\")\n        .set_key(\"<API_KEY>\");\n\n    let messaging = Messaging::new(&client);\n\n    let message = messaging.create_email(\n        \"<MESSAGE_ID>\",                              // messageId\n        \"<SUBJECT>\",                                 // subject\n        \"<CONTENT>\",                                 // content\n        None,                                        // topics (optional)\n        None,                                        // users (optional)\n        None,                                        // targets (optional)\n        None,                                        // cc (optional)\n        None,                                        // bcc (optional)\n        None,                                        // attachments (optional)\n        None,                                        // draft (optional)\n        None,                                        // html (optional)\n        None,                                        // scheduledAt (optional)\n    ).await?;\n\n    println!(\"{:?}\", message);\n    Ok(())\n}\n```\n{% /multicode %}\n{% /tabsitem %}\n{% /tabs %}\n\nYou can follow the [Send email messages](/docs/products/messaging/send-push-notifications) guide to send your first push notification and test your provider.\n{% /section %}\n\n{% section #manage-provider step=4 title=\"Manage provider\" %}\n{% tabs %}\n{% tabsitem #console title=\"Console\" %}\nYou can update or delete a provider in the Appwrite Console.\n\nNavigate to **Messaging** > **Providers** > click your provider.\nIn the settings, you can update a provider's configuration or delete the provider.\n{% /tabsitem %}\n\n{% tabsitem #server-sdk title=\"Server SDK\" %}\nTo update or delete providers programmatically, use an [Appwrite Server SDK](/docs/sdks#server).\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\n// Init SDK\nconst client = new sdk.Client();\n\nconst messaging = new sdk.Messaging(client);\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>') // Your project ID\n    .setKey('<API_KEY>') // Your secret API key\n;\n\n// update provider\nmessaging.updateSmtpProvider({\n    providerId: '<PROVIDER_ID>',\n    name: '<PROVIDER_NAME>',\n    host: '<HOST>',\n    port: 587,\n    username: '<USERNAME>',\n    password: '<PASSWORD>',\n    encryption: sdk.SmtpEncryption.Tls,\n    autoTLS: true,\n    mailer: '<MAILER>',\n    fromName: '<SENDER_NAME>',\n    fromEmail: '<SENDER_EMAIL>',\n    replyToName: '<REPLY_TO_NAME>',\n    replyToEmail: '<REPLY_TO_EMAIL>',\n    enabled: true\n}).then(function (response) {\n    console.log(response);\n}, function (error) {\n    console.log(error);\n});\n\n// delete provider\nmessaging.deleteProvider({\n    providerId: '<PROVIDER_ID>'\n})\n.then(function (response) {\n    console.log(response);\n}, function (error) {\n    console.log(error);\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\n// Init SDK\nlet client = new sdk.Client();\n\nlet messaging = new sdk.Messaging(client);\n\n// update provider\nmessaging.updateSmtpProvider({\n    providerId: '<PROVIDER_ID>',\n    name: '<PROVIDER_NAME>',\n    host: '<HOST>',\n    port: 587,\n    username: '<USERNAME>',\n    password: '<PASSWORD>',\n    encryption: sdk.SmtpEncryption.Tls,\n    autoTLS: true,\n    mailer: '<MAILER>',\n    fromName: '<SENDER_NAME>',\n    fromEmail: '<SENDER_EMAIL>',\n    replyToName: '<REPLY_TO_NAME>',\n    replyToEmail: '<REPLY_TO_EMAIL>',\n    enabled: true\n}).then(function (response) {\n    console.log(response);\n}, function (error) {\n    console.log(error);\n});\n\n// delete provider\nmessaging.deleteProvider({\n    providerId: '<PROVIDER_ID>'\n})\n.then(function (response) {\n    console.log(response);\n}, function (error) {\n    console.log(error);\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\Messaging;\n\n$client = new Client();\n\n$client\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<PROJECT_ID>') // Your project ID\n    ->setKey('<API_KEY>') // Your secret API key\n;\n\n$messaging = new Messaging($client);\n\n$result = $messaging->updateSendgridProvider(\n    '<PROVIDER_ID>',\n    '<PROVIDER_NAME>',\n    '<API_KEY>',\n    '<DOMAIN>',\n    '<IS_EU_REGION?>',\n    '<SENDER_NAME>',\n    '<SENDER_EMAIL>',\n    '<REPLY_TO_NAME>',\n    '<REPLY_TO_EMAIL>',\n    '<ENABLED?>',\n);\n```\n```python\nfrom appwrite.client import Client\n\nclient = Client()\n\n(client\n  .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n  .set_project('<PROJECT_ID>') # Your project ID\n  .set_key('<API_KEY>') # Your secret API key\n)\n\nmessaging = Messaging(client)\n\nresult = messaging.update_smtp_provider(\n    provider_id='<PROVIDER_ID>',\n    name='<PROVIDER_NAME>',\n    host='<HOST>',\n    port=587,\n    username='<USERNAME>',\n    password='<PASSWORD>',\n    encryption='tls',\n    auto_tls=True,\n    mailer='<MAILER>',\n    from_name='<SENDER_NAME>',\n    from_email='<SENDER_EMAIL>',\n    reply_to_name='<REPLY_TO_NAME>',\n    reply_to_email='<REPLY_TO_EMAIL>',\n    enabled=True,\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<PROJECT_ID>') # Your project ID\n    .set_key('<API_KEY>') # Your secret API key\n\nmessaging = Messaging.new(client)\n\nresponse = messaging.update_sendgrid_provider(\n    provider_id: \"<PROVIDER_ID>\",\n    name: \"<PROVIDER_NAME>\",\n    api_key: \"<API_KEY>\",\n    domain: \"<DOMAIN>\",\n    isEuRegion: \"<IS_EU_REGION?>\",\n    from_name: \"<SENDER_NAME>\",\n    from_email: \"<SENDER_EMAIL>\",\n    reply_to_name: \"<REPLY_TO_NAME>\",\n    reply_to_email: \"<REPLY_TO_EMAIL>\",\n    enabled: \"<ENABLED?>\",\n)\n\nputs response.inspect\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Services;\nusing Appwrite.Models;\nusing Appwrite.Enums;\n\nvar client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<PROJECT_ID>\") // Your project ID\n    .SetKey(\"<API_KEY>\"); // Your secret API key\n\nvar messaging = new Messaging(client);\n\nProvider result = await messaging.UpdateSendgridProvider(\n    providerId: \"<PROVIDER_ID>\",\n    name: \"<PROVIDER_NAME>\",\n    apiKey: \"<API_KEY>\",\n    domain: \"<DOMAIN>\",\n    isEuRegion: \"<IS_EU_REGION?>\",\n    fromName: \"<SENDER_NAME>\",\n    fromEmail: \"<SENDER_EMAIL>\",\n    replyToName: \"<REPLY_TO_NAME>\",\n    replyToEmail: \"<REPLY_TO_EMAIL>\",\n    enabled: \"<ENABLED?>\",\n);\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\nimport 'package:dart_appwrite/enums.dart';\nimport 'package:dart_appwrite/models.dart';\n\nvoid main() { // Init SDK\n  Client client = Client();\n  Messaging messaging = Messaging(client);\n\n  client\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<PROJECT_ID>') // Your project ID\n    .setKey('<API_KEY>') // Your secret API key\n  ;\n\n  Future result = messaging.updateSendgridProvider(\n    providerId: \"<PROVIDER_ID>\",\n    name: \"<PROVIDER_NAME>\",\n    apiKey: \"<API_KEY>\",\n    domain: \"<DOMAIN>\",\n    isEuRegion: \"<IS_EU_REGION?>\",\n    fromName: \"<SENDER_NAME>\",\n    fromEmail: \"<SENDER_EMAIL>\",\n    replyToName: \"<REPLY_TO_NAME>\",\n    replyToEmail: \"<REPLY_TO_EMAIL>\",\n    enabled: \"<ENABLED?>\",\n  );\n\n  result\n    .then((response) {\n      print(response);\n    }).catchError((error) {\n      print(error.response);\n  });\n}\n```\n```kotlin\nimport io.appwrite.Client\nimport io.appwrite.coroutines.CoroutineCallback\nimport io.appwrite.services.Messaging\n\nval client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\") // Your project ID\n    .setKey(\"<API_KEY>\") // Your secret API key\n\nval messaging = Messaging(client)\n\nval response = messaging.updateSendgridProvider(\n    providerId = \"<PROVIDER_ID>\",\n    name = \"<PROVIDER_NAME>\",\n    apiKey = \"<API_KEY>\",\n    domain = \"<DOMAIN>\",\n    isEuRegion = \"<IS_EU_REGION?>\",\n    fromName = \"<SENDER_NAME>\",\n    fromEmail = \"<SENDER_EMAIL>\",\n    replyToName = \"<REPLY_TO_NAME>\",\n    replyToEmail = \"<REPLY_TO_EMAIL>\",\n    enabled = \"<ENABLED?>\",\n)\n\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.Messaging;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\") // Your project ID\n    .setKey(\"<API_KEY>\"); // Your secret API key\n\nMessaging messaging = new Messaging(client);\n\nmessaging.updateSendgridProvider(\n    \"<PROVIDER_ID>\",\n    \"<PROVIDER_NAME>\",\n    \"<API_KEY>\",\n    \"<DOMAIN>\",\n    \"<IS_EU_REGION?>\",\n    \"<SENDER_NAME>\",\n    \"<SENDER_EMAIL>\",\n    \"<REPLY_TO_NAME>\",\n    \"<REPLY_TO_EMAIL>\",\n    \"<ENABLED?>\",\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```swift\nimport Appwrite\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<PROJECT_ID>\") // Your project ID\n    .setKey(\"<API_KEY>\") // Your secret API key\n\nlet messaging = Messaging(client)\n\nlet provider = try await messaging.updateSendgridProvider(\n    providerId: \"<PROVIDER_ID>\",\n    name: \"<PROVIDER_NAME>\",\n    apiKey: \"<API_KEY>\",\n    domain: \"<DOMAIN>\",\n    isEuRegion: \"<IS_EU_REGION?>\",\n    fromName: \"<SENDER_NAME>\",\n    fromEmail: \"<SENDER_EMAIL>\",\n    replyToName: \"<REPLY_TO_NAME>\",\n    replyToEmail: \"<REPLY_TO_EMAIL>\",\n    enabled: \"<ENABLED?>\",\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::messaging::Messaging;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new()\n        .set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\")\n        .set_project(\"<PROJECT_ID>\")\n        .set_key(\"<API_KEY>\");\n\n    let messaging = Messaging::new(&client);\n\n    // update provider\n    let provider = messaging.update_smtp_provider(\n        \"<PROVIDER_ID>\",                             // providerId\n        Some(\"<PROVIDER_NAME>\"),                     // name (optional)\n        Some(\"<HOST>\"),                              // host (optional)\n        Some(587),                                   // port (optional)\n        Some(\"<USERNAME>\"),                          // username (optional)\n        Some(\"<PASSWORD>\"),                          // password (optional)\n        None,                                        // encryption (optional)\n        Some(true),                                  // autoTLS (optional)\n        Some(\"<MAILER>\"),                            // mailer (optional)\n        Some(\"<SENDER_NAME>\"),                       // fromName (optional)\n        Some(\"<SENDER_EMAIL>\"),                      // fromEmail (optional)\n        Some(\"<REPLY_TO_NAME>\"),                     // replyToName (optional)\n        Some(\"<REPLY_TO_EMAIL>\"),                    // replyToEmail (optional)\n        Some(true),                                  // enabled (optional)\n    ).await?;\n\n    // delete provider\n    messaging.delete_provider(\"<PROVIDER_ID>\").await?;\n\n    println!(\"{:?}\", provider);\n    Ok(())\n}\n```\n{% /multicode %}\n{% /tabsitem %}\n{% /tabs %}\n{% /section %}\n";
